    11	public final class TourismsTaxReport extends CsvReport {
    12	
    13	    private static final BigDecimal TAX_PER_GUEST_PER_NIGHT = new BigDecimal("4.50");
    14	
    15	    private final ReservationStore store;
    16	
    17	    public TourismsTaxReport(ReservationStore store) {
    18	        this.store = store;
    19	    }
    20	
    21	    public String generate(YearMonth month) {
    22	        List<Reservation> paidReservations = new ArrayList<>();
    23	        for (Reservation reservation : store.all()) {
    24	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
    25	            if (reservation.isPaid() && startsInMonth) {
    26	                paidReservations.add(reservation);
    27	            }
    28	        }
    29	        paidReservations.sort(Comparator.comparing(Reservation::checkIn).thenComparingLong(Reservation::id));
    30	
    31	        StringBuilder rows = new StringBuilder();
    32	        BigDecimal totalTax = BigDecimal.ZERO.setScale(2);
    33	        for (Reservation reservation : paidReservations) {
    34	            long nights = reservation.checkOut().toEpochDay() - reservation.checkIn().toEpochDay();
    35	            BigDecimal reservationTax = TAX_PER_GUEST_PER_NIGHT.multiply(BigDecimal.valueOf(reservation.guests() * nights)).setScale(2, java.math.RoundingMode.HALF_EVEN);
    36	            rows.append(reservation.id()).append(',')
    37	                    .append(reservation.roomNumber()).append(',')
    38	                    .append(reservation.checkIn()).append(',')
    39	                    .append(reservation.checkOut()).append(',')
    40	                    .append(reservation.guests()).append(',')
    41	                    .append(nights).append(',')
    42	                    .append(reservationTax.toPlainString()).append('\n');
    43	            totalTax = totalTax.add(reservationTax);
    44	        }
    45	        String total = "total," + totalTax.toPlainString() + "\n";
    46	
    47	        return formatCsv("tourism-tax", month.toString(), "reservation,room,check_in,check_out,guests,nights,tax", rows.toString(), total);
    48	    }
    19	    public String generate(YearMonth month) {
    20	        List<Reservation> withRevenue = new ArrayList<>();
    21	        for (Reservation reservation : store.all()) {
    22	            boolean keptMoney = reservation.amountKept().signum() > 0;
    23	            boolean startsInMonth = YearMonth.from(reservation.checkIn()).equals(month);
    24	            if (keptMoney && startsInMonth) {
    25	                withRevenue.add(reservation);
    26	            }
    27	        }
    28	
    29	        StringBuilder rows = new StringBuilder();
    30	        int totalReservations = 0;
    31	        BigDecimal totalAmount = BigDecimal.ZERO.setScale(2);
    32	
    33	        for (RatePlan plan : RatePlan.values()) {
    34	            int reservationCount = 0;
    35	            BigDecimal planAmount = BigDecimal.ZERO.setScale(2);
    36	            for (Reservation reservation : withRevenue) {
    37	                if (reservation.ratePlan() == plan) {
    38	                    reservationCount++;
    39	                    planAmount = planAmount.add(reservation.amountKept());
    40	                }
    41	            }
    42	            rows.append(plan).append(',')
    43	                    .append(reservationCount).append(',')
    44	                    .append(planAmount.toPlainString()).append('\n');
    45	            totalReservations += reservationCount;
    46	            totalAmount = totalAmount.add(planAmount);
    47	        }
    48	
    49	        String total = "total," + totalReservations + "," + totalAmount.toPlainString() + "\n";
    50	
    51	        return formatCsv("rate-plans", month.toString(), "rate_plan,reservations,amount", rows.toString(), total);
    52	    }
